t['requirements']['T12']={'applicable':True,'status':'unverified','reason':'Full author route/source/help audit completed; no external SASIS, actual destination acceptance or root full final check certified. Original immutable artifacts preserved for whole audit before repair.','evidence':[ev('audit/author-audit.md','No v2 or learner edit has occurred.')],'dependencies':[]}
t['gaps']=[{'id':'destination','question':'Does the actual GitHub destination preserve all expressions, prose typography, images and help navigation?','consequential':True,'status':'unverified','reason':'Author did only source checks and local plot inspection. Root reports a separate destination math defect, whose detailed evidence belongs to external audit.','next_action':'Root complete original destination audit; consolidate with source, author, technical and fresh SASIS before any repair.','evidence':[],'dependencies':[]},{'id':'lexical-false-positive','question':'Are four command-before-digit payloads an established violation of the r23 dollar/backtick-specific space instruction?','consequential':False,'status':'resolved','reason':'No: exact source shows plain-dollar inline delimiters without backticks. Original checker over-applied a conditional rule. Original failed report preserved and disposition appended; no learner repair justified by that report alone.','next_action':'Keep original evidence; any destination fault is independently diagnosed.','evidence':[ev('audit/mechanical-disposition.json','"disposition": "withdrawn_as_established_instruction_violation"')],'dependencies':td}]
def cond(cid,desc,status,reason,witness=None):return {'id':cid,'description':desc,'applicable':True,'status':status,'reason':reason,'evidence':[] if witness is None else [ev(*witness)],'dependencies':gd if status=='pass' else []}
